<?php require 'config/db.php';$order=null;$items=[];if(isset($_GET['id'])){$s=$pdo->prepare('SELECT o.*,p.method,p.status payment_status FROM orders o LEFT JOIN payments p ON p.order_id=o.id WHERE o.id=?');$s->execute([(int)$_GET['id']]);$order=$s->fetch();if($order){$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$order['id']]);$items=$s->fetchAll();}}?><!doctype html><html><head><meta charset="utf-8"><title>Order Status</title><link rel="stylesheet" href="css/style.css"></head><body><main class="container"><h1>Track Order</h1><?php if(!$order):?><form class="form-card" method="get"><input type="number" name="id" placeholder="Order ID" required><button class="btn">Track</button></form><?php else:?><div class="form-card"><h2>Order #<?=$order['id']?></h2><p><b>Status:</b> <?=e($order['status'])?></p><p><b>Customer:</b> <?=e($order['customer_name'])?></p><p><b>Payment:</b> <?=e($order['method'])?> — <?=e($order['payment_status'])?></p><p><b>Total:</b> $<?=number_format($order['total'],2)?></p><?php foreach($items as $i):?><p><?=e($i['drink_name'])?> × <?=$i['qty']?> — <?=e($i['size'])?>, <?=e($i['sugar'])?>, <?=e($i['ice'])?></p><?php endforeach;?><a class="btn" href="index.php">Home</a></div><?php endif;?></main></body></html>
